import {createTurnScene} from './turn-scene.js';
import {TURN_SOURCE,TURN_ANCHOR,TURN_LEGAL_SOURCE,TURN_LEGAL_ANCHOR,TURN_VOICE,addTurnEvent,turnCurrent,turnSummary} from './turn-learning.js';
import {renderArt} from './art.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const phaseOrder=['observe','risk','decision','consequence','explain','transfer','contrast','recall','done'];
const choice=(id,title,detail='')=>`<button class="turn-choice" data-turn-answer="${id}"><span>${title}</span>${detail?`<small>${detail}</small>`:''}<b aria-hidden="true">→</b></button>`;
const next=(text,disabled=false)=>`<button class="turn-primary" data-turn-action="next"${disabled?' disabled':''}>${text}<span aria-hidden="true">→</span></button>`;
const options=()=>choice('wait','Hold tilbage for cyklisten','Orientér dig igen. Drej, når det er frit.')+choice('turn','Drej nu','Du har allerede tændt blinklyset.')+choice('horn','Giv et kort dyt og drej','Så ved cyklisten, at du kommer.');
export function renderTurnEntry(profile,now=Date.now()) {
  const summary=turnSummary(profile,now);const current=summary.latest;
  const label=current && current.stage!=='done'?'Fortsæt situationen':summary.reviewDue?'Prøv din uge-test':summary.first?'Se situationen igen':'Tag plads bag rattet';
  return `<a class="turn-entry" href="#trafiklab" aria-label="${label}: Et blink. To baner."><span class="turn-entry__mark" aria-hidden="true">↱</span><span><small>TRAFIKLAB · CA. 3 MIN</small><strong>Et blink. To baner.</strong><span>${summary.reviewDue?'En ny situation venter. Hvad husker du?':'Undersøg. Vælg. Se, hvad der sker.'}</span></span><b>${label} <span aria-hidden="true">↗</span></b></a>`;
}
export function createTurnLesson({host,getProfile,persist,settings,narrator,onSound=()=>{}}) {
  let disposed=false,world=null,renderedStage='',renderedAttempt='',replayAttempt='',replayReady=false,stageSince=performance.now();
  const stamp=()=>Math.max(Date.now(),...(getProfile()?.events||[]).map(e=>e.at+1));
  const uid=()=>globalThis.crypto?.randomUUID?.()||`turn-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  function event(type,value='') {const current=turnCurrent(getProfile());const at=stamp();persist(addTurnEvent(getProfile(),{id:uid(),attemptId:current?.id||uid(),at,type,value,latencyMs:['answer','point','commit'].includes(type)?Math.round(performance.now()-stageSince):undefined}));}
  function start(review=false) {const id=uid();persist(addTurnEvent(getProfile(),{id,attemptId:id,at:stamp(),type:'start',value:review?'review':'lesson'}));}
  function voiceKey(state) {return ({'consequence':state.decision==='wait'?'safe':'unsafe','explain':'explain','repair':'explain','transfer-feedback':'transferExplain','transfer':state.review?'review':'transfer','recall-check':'recallCheck','recall-feedback':state.recall==='repeat'?'recallSaved':'recallRepair','risk-feedback':'riskExplain','contrast-feedback':'contrastExplain'})[state.stage]||state.stage;}

  function content(state) {
    const s=turnSummary(getProfile()), humor=settings().humor;
    const heading=(k,t,p)=>`<span class="turn-kicker">${k}</span><h1 id="turn-heading">${t}</h1><p class="turn-lead">${p}</p>`;
    const legalSource=()=>`<details class="turn-source"><summary>${state.review?'Reglen ved højresvinget':'Reglen ved indkørslen'}</summary><a href="${TURN_LEGAL_SOURCE}" target="_blank" rel="noopener">${TURN_LEGAL_ANCHOR} ↗</a><p>${state.review?'Ved højresving skal du holde tilbage for cyklisten, der fortsætter ligeud.':'Samme regel ved højresving over en cykelsti uden for et vejkryds.'} Kildekontrolleret; afventer kvalificeret kørelærergennemgang.</p></details>`;
    const result=(good,title,text)=>`<div class="turn-feedback ${good?'turn-feedback--good':'turn-feedback--repair'}" role="status"><span>${good?'✓':'↻'}</span><div><strong>${title}</strong><p>${text}</p></div></div>`;
    switch(state.stage){
      case 'observe':return heading('01 / UNDERSØG','Et blink.<br><em>To baner.</em>','Du holder stille og vil til højre. Undersøg højresiden, før du vælger dit næste træk.')+`<div class="turn-instruction"><span aria-hidden="true">↗</span><p>${state.viewed.includes('shoulder')?'Højresiden er åben. Find den relevante risiko i næste trin.':'Skift fra forruden til højresiden med knappen over billedet.'}</p></div>`+next('Jeg er klar til at vælge',!state.viewed.includes('shoulder'));
      case 'risk':return heading('02 / OPDAG','Find risikoen.','Tryk på den trafikant i billedet, du skal holde øje med før svinget.')+'<p class="turn-point-hint">↖ Tryk direkte i trafikscenen.</p><details class="turn-text-alternative"><summary>Besvar med tekst i stedet</summary><div class="turn-choices">'+choice('cycle','Cyklisten på højresiden','Følg dens bane frem mod svinget.')+choice('exit','Kun vejen, jeg vil dreje ind på','Hvis den er tom, kan jeg fuldføre svinget.')+choice('road','Kun bilerne foran mig','Så længe de kører, kan jeg også køre.')+'</div></details>';
      case 'risk-feedback':return heading('OPDAG / DIT SVAR',state.risk==='cycle'?'Følg den bane,<br><em>du vil krydse.</em>':'Dit sving<br><em>krydser en cykelsti.</em>','Cyklisten kan komme fra bag bilen til siden. En tom vej foran bilen siger ikke, at cykelstien er fri.')+result(state.risk==='cycle',state.risk==='cycle'?'Du fandt det relevante område':'Undersøg også højresiden','Bliv ved med at følge cyklisternes bevægelse, og gentag orienteringen lige før svinget.')+(state.risk==='cycle'?next('Vælg min handling'):'<button class="turn-primary" data-turn-action="retry">Find området igen <span>↻</span></button>');
      case 'decision':return heading('03 / DIT TRÆK','Du blinker.<br><em>Hvem kører først?</em>','Cyklisten kommer bagfra og fortsætter ligeud. Du vil til højre.')+`<div class="turn-choices">${options()}</div>`;
      case 'consequence':return heading('04 / KONSEKVENS',state.decision==='wait'?'Plads til begge.':'Her mødes banerne.',state.decision==='wait'?'Se cyklisten passere, før bilen drejer.':'Visningen stopper før kontakt. Se, hvor svinget krydser cyklistens bane.')+`<div class="turn-replay-status" role="status">${replayReady?'Forløbet er vist.':'Viser dit valg…'}</div><button class="turn-text-btn" data-turn-action="replay">↻ Se forløbet igen</button>`+next('Hvorfor sker det?',!replayReady);
      case 'explain':return heading('05 / FORSTÅ','Blinklys er<br><em>en besked.</em>','Det giver dig ikke forrang. Ved højresving må du ikke være til fare eller ulempe for cyklister, der fortsætter ligeud.')+`<div class="turn-rule"><b>Se tidligt. Se igen.</b><p>Orientér dig i spejle og blind vinkel før placering. Gentag kontrollen lige før svinget. Hold tilbage, og drej først, når det er frit.</p></div>${humor?'<p class="turn-gag">Din bil har ikke plot armor.</p>':''}<details class="turn-source"><summary>Kilde & faglig status</summary><a href="${TURN_SOURCE}" target="_blank" rel="noopener">Færdselsstyrelsens undervisningsplan ↗</a><p>${TURN_ANCHOR}. Kildebaseret prototype. Afventer kvalificeret kørelærergennemgang.</p></details>`+next(state.decision==='wait'?'Prøv en anden vej':'Reparér dit valg');
      case 'repair':return heading('OMKAMP / SAMME REGEL','Giv cyklisten<br><em>plads.</em>','Dit første valg er gemt. Brug forklaringen til at vælge en sikker handling.')+(state.decision && state.decision!=='wait'?result(false,'Prøv handlingen igen','Et blink eller et dyt flytter ikke cyklisten og ændrer ikke din pligt.'):'')+`<div class="turn-choices">${options()}</div>`;
      case 'transfer':return heading(state.review?'UGE-TEST / NY SITUATION':'06 / NY SITUATION',state.review?'En uge senere.<br><em>Dit eget blik.</em>':'Ny vej.<br><em>Samme ansvar?</em>',state.review?'Du vil til højre i et T-kryds. Cyklisten på højresiden fortsætter ligeud. Hvad afgør, om du kan dreje?':'Du skal ind ad en indkørsel over en gennemgående cykelsti. En cyklist kommer bagfra. Hvad afgør, om du kan dreje?')+`<div class="turn-choices">${choice('green','At din bane har grønt eller fri vej','Så kan du fortsætte dit sving.')}${choice('yield','At du har orienteret dig, og svinget er frit','Hold tilbage for cyklisten, der fortsætter ligeud.')}${choice('signal','At du har blinket i god tid','Så skal cyklisten tilpasse sig.')}</div>`;
      case 'transfer-feedback':return heading('NY SITUATION / DIT SVAR',state.transfer==='yield'?'Reglen flytter<br><em>med dig.</em>':'Se på banen,<br><em>du krydser.</em>',state.review?'T-krydset ændrer vejens udseende. Bilen skal stadig over cyklistens bane.':'Indkørslen ændrer vejens udseende. Bilen skal stadig over cyklistens bane.')+result(state.transfer==='yield',state.transfer==='yield'?'Et sikkert valg':'Her skal valget repareres',state.transfer==='yield'?'Du har valgt at orientere dig og holde tilbage. Ét svar i en ny variant siger noget om dette valg, ikke om hele din kunnen.':'Fri vej for bilen eller et tændt blinklys giver ikke forrang over cyklisten.')+legalSource()+(state.transfer==='yield'?next('Vurdér én vigtig forskel'):'<button class="turn-primary" data-turn-action="retry">Vælg igen <span>↻</span></button>');
      case 'contrast':return heading('KONTRAST / HVAD ER ANDERLEDES?','Cyklisten er forbi.<br><em>Dit træk nu?</em>','Samme vej. Cyklisten er allerede forbi svingstedet. Ingen andre trafikanter er i nærheden, og du har frit udsyn.')+'<div class="turn-choices">'+choice('always-wait','Jeg bliver holdende på grund af cyklisten','Jeg må aldrig dreje, når der er cyklister på vejen.')+choice('proceed','Jeg orienterer mig igen og drejer, når det er frit','Den passerede cyklist spærrer ikke længere min bane.')+choice('skip-check','Jeg drejer uden at undersøge højresiden igen','Cyklisten er jo allerede forbi.')+'</div>';
      case 'contrast-feedback':return heading('KONTRAST / DIT SVAR',state.contrast==='proceed'?'Giv plads.<br><em>Kør, når der er plads.</em>':'Vent på en fri bane.<br><em>Ikke på ingenting.</em>','Reglen kræver, at dit sving kan ske uden at genere eller udsætte andre for fare. Den kræver ikke, at du altid venter.')+result(state.contrast==='proceed',state.contrast==='proceed'?'Du skelnede mellem situationerne':'Brug den nye placering','Cyklisten er forbi konfliktstedet. Orientér dig igen. Når svinget er frit, kan du dreje.')+(state.contrast==='proceed'?next('Hent reglen frem'):'<button class="turn-primary" data-turn-action="retry">Vurdér den frie bane igen <span>↻</span></button>');
      case 'recall':return heading('07 / HENT FREM','Hvad gør du<br><em>lige før svinget?</em>','Du så i spejlet i god tid. Formulér nu selv, hvad du skal gøre, før du drejer.')+'<label class="turn-recall-label" for="turn-recall">Skriv dit svar, eller sig det højt for dig selv</label><textarea id="turn-recall" maxlength="600" rows="3" placeholder="Mit næste blik og min handling…">'+esc(state.recallText)+'</textarea><p class="turn-review-note">Dit svar bliver i denne browser. Ingen AI bedømmer det.</p><button class="turn-primary" data-turn-action="commit">Jeg har mit svar · vis reglen <span>→</span></button>';
      case 'recall-check':return heading('SELVTJEK / SAMMENLIGN','Var begge dele<br><em>med i dit svar?</em>','1. Gentag orienteringen i spejle og blind vinkel lige før svinget. 2. Hold tilbage for cyklisten, og drej først, når det er frit.')+(state.recallText?'<blockquote class="turn-own-answer">'+esc(state.recallText)+'</blockquote>':'<p class="turn-review-note">Sammenlign med det svar, du formulerede for dig selv.</p>')+'<div class="turn-choices">'+choice('repeat','Begge dele var med','Mit eget selvtjek — ingen automatisk bedømmelse.')+choice('once','Jeg manglede et eller flere punkter','Jeg vil hente handlingen frem én gang mere.')+choice('signal','Jeg er usikker på mit svar','Jeg vil sammenligne og prøve igen.')+'</div>';
      case 'recall-feedback':return heading('GENKALDELSE / DIT SVAR',state.recall==='repeat'?'Et nyt blik.<br><em>Et bedre træk.</em>':'Et gammelt blik<br><em>bliver gammelt.</em>','En cyklist kan nå fra bag bilen til siden, mens du nærmer dig svinget.')+result(state.recall==='repeat',state.recall==='repeat'?'Dit selvtjek er gemt':'Tag handlingen én gang mere','Se tidligt i spejle og blind vinkel, og gentag orienteringen lige før svinget.')+(state.recall==='repeat'?next('Gem mit forløb'):'<button class="turn-primary" data-turn-action="retry">Hent frem igen <span>↻</span></button>');
      case 'done':return `<div class="turn-done-art">${humor?renderArt('koerelys-brain',{variant:'result',humorOnly:true}):'<span aria-hidden="true">✓</span>'}</div>`+heading('FORLØB GEMT','Et bedre blik.<br><em>Dit næste træk.</em>','Du har gennemført situationen. Her er, hvad dine svar viser:')+`<ul class="turn-evidence"><li><span>Risikoen</span><b>${state.firstRisk===null?'Ikke gentestet':state.firstRisk==='cycle'?(state.firstRiskMethod==='image'?'Udpeget i billedet':'Valgt med tekst'):'Gennemgået med hjælp'}</b></li><li><span>Første handling</span><b>${state.firstDecision===null?'Ikke gentestet':state.firstDecision==='wait'?'Sikkert første valg':'Repareret'}</b></li><li><span>Ny vej</span><b>${state.firstTransfer==='yield'?'Løst første gang':'Gennemgået med hjælp'}</b></li><li><span>Da banen var fri</span><b>${state.firstContrast==='proceed'?'Skelnet første gang':'Gennemgået med hjælp'}</b></li><li><span>Dit selvtjek nu</span><b>${state.firstRecall==='repeat'?'Selvtjek: begge med':'Selvtjek: øvet igen'}</b></li><li><span>Genkaldelse efter en uge</span><b>${s.delayed?'Afprøvet i appen':'Ikke afprøvet endnu'}</b></li></ul><p class="turn-review-note">${s.delayed?'En uge-test er gennemført. Det er stadig afgrænset til appens situationer.':`Din uge-test åbner ${new Intl.DateTimeFormat('da-DK',{day:'numeric',month:'long'}).format(new Date(s.dueAt||Date.now()))}. Din fremgang er gemt i denne browser.`}</p><a class="turn-primary" href="#home">Til din rute <span>↗</span></a><button class="turn-text-btn" data-turn-action="restart">Øv samme forløb igen</button>${s.reviewDue?'<button class="turn-primary" data-turn-action="review">Tag uge-testen</button>':''}`;
      default:return '';
    }
  }
  function render({focus=false}={}) {
    if(disposed)return;let state=turnCurrent(getProfile());if(!state){start();state=turnCurrent(getProfile());}
    if(!world){
      host.innerHTML=`<div class="turn-shell"><header class="turn-top"><a href="#home" aria-label="Gem og gå til din rute">←</a><span>TRAFIKLAB <i>/</i> CA. 3 MIN</span><button class="turn-listen" data-turn-action="listen" aria-label="Lyt til dette trin">◖ Lyt</button></header><div class="turn-meter" role="progressbar" aria-label="Forløbets trin" aria-valuemin="0" aria-valuemax="8"><span></span></div><div class="turn-layout"><figure class="turn-stage"><div class="turn-viewbar" role="group" aria-label="Undersøg trafiksituationen"><button data-turn-view="driver">Forrude</button><button data-turn-view="shoulder">Højreside</button><button data-turn-view="overhead">Overblik</button></div><div class="turn-canvas-wrap"><canvas class="turn-canvas" role="img" aria-label="Kontrolleret dansk trafiksituation med en bil, der vil til højre over en cykelsti"></canvas><div class="turn-scene-tag"><span></span><b>DU HOLDER STILLE</b></div></div><p class="turn-sr turn-view-description" aria-live="polite"></p><figcaption>Illustreret øvesituation · billedet viser ikke en officiel teoriprøve.</figcaption></figure><section class="turn-body" aria-labelledby="turn-heading"></section></div></div>`;
      world=createTurnScene(host.querySelector('canvas'),{motion:settings().motion,variant:'junction',onReplayEnd(){if(disposed||turnCurrent(getProfile())?.id!==replayAttempt)return;replayReady=true;const tag=host.querySelector('.turn-scene-tag b');if(tag)tag.textContent='DIT VALG ER VIST';host.querySelector('.turn-replay-status')?.replaceChildren(document.createTextNode('Forløbet er vist.'));const b=host.querySelector('[data-turn-action="next"]');if(turnCurrent(getProfile())?.stage==='consequence'&&b)b.disabled=false;}});
    }
    const previous=renderedStage;const attemptChanged=state.id!==renderedAttempt;const change=state.stage!==previous||attemptChanged;if(change)stageSince=performance.now();if(change&&state.stage==='consequence')replayReady=false;if(attemptChanged)world.reset();renderedStage=state.stage;renderedAttempt=state.id;
    const isNew=['transfer','transfer-feedback','contrast','contrast-feedback'].includes(state.stage)||state.review;
    const variant=state.review?'review':isNew?'driveway':'junction';
    if(world.snapshot().variant!==variant)world.setVariant(variant);
    world.setMotion(settings().motion);world.setCyclistCleared?.(['contrast','contrast-feedback'].includes(state.stage));
    world.setExplanation(['explain','repair','transfer-feedback','contrast-feedback'].includes(state.stage));
    if(state.stage==='recall'||state.stage==='recall-feedback'||state.stage==='recall-check'||state.stage==='done')host.querySelector('.turn-stage').hidden=true;else host.querySelector('.turn-stage').hidden=false;
    host.querySelector('.turn-layout').classList.toggle('turn-layout--recall',['recall','recall-check','recall-feedback','done'].includes(state.stage));
    host.querySelectorAll('[data-turn-view]').forEach(b=>{b.hidden=b.dataset.turnView==='overhead'&&['observe','risk','risk-feedback','decision','transfer'].includes(state.stage);b.setAttribute('aria-pressed',String(b.dataset.turnView===state.view));});
    world.setView(state.view);
    host.querySelector('.turn-stage').classList.toggle('turn-stage--pick',state.stage==='risk');
    const description=['contrast','contrast-feedback'].includes(state.stage)?`${state.view==='shoulder'?'Højresiden':state.view==='driver'?'Forruden':'Overblik'}: cyklisten er allerede forbi svingstedet på cykelstien. Bilen holder før svinget. Der er ingen andre trafikanter i nærheden.`:state.view==='shoulder'?'Højresiden: en cyklist kommer bag bilen på cykelstien i samme retning.':state.view==='overhead'?'Overblik: bilen drejer til højre og krydser cyklistens ligeudgående bane.':'Forruden: du holder i højre side af vejen. Cykelstien løber langs bilens højre side. Undersøg højresiden for trafik bagfra.';
    host.querySelector('canvas').setAttribute('aria-label',description);host.querySelector('.turn-view-description').textContent=description;
    const tag=host.querySelector('.turn-scene-tag b');tag.textContent=state.stage==='risk'?'TRYK PÅ RISIKOEN':['contrast','contrast-feedback'].includes(state.stage)?'CYKLISTEN ER FORBI':state.stage==='consequence'?(replayReady?'DIT VALG ER VIST':'DIT VALG AFSPILLES'):state.stage==='transfer-feedback'||state.stage==='explain'?'SÅDAN KRYDSER BANERNE':'DU HOLDER STILLE';
    const index=phaseOrder.indexOf(state.stage.replace(/-(feedback|check)$/,''));const progress=Math.max(0,index<0?4:index);
    const meter=host.querySelector('.turn-meter');meter.setAttribute('aria-valuenow',String(progress));meter.firstElementChild.style.width=`${progress/8*100}%`;
    const body=host.querySelector('.turn-body');body.innerHTML=content(state);
    if(change&&settings().motion)body.animate?.([{opacity:0,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.2,.8,.2,1)'});
    if(change&&state.stage==='consequence'){replayReady=false;replayAttempt=state.id;world.replay(state.decision==='wait'?'wait':'turn');}
    if(focus){body.querySelector('h1')?.setAttribute('tabindex','-1');body.querySelector('h1')?.focus({preventScroll:true});if(window.innerWidth<800)host.querySelector('.turn-top').scrollIntoView({behavior:'instant',block:'start'});}
  }
  function click(e) {
    const b=e.target.closest('button');if(!b||!host.contains(b)||b.disabled)return;
    const state=turnCurrent(getProfile());if(state.id!==renderedAttempt||state.stage!==renderedStage){render({focus:true});const notice=document.createElement('p');notice.className='turn-review-note';notice.setAttribute('role','status');notice.textContent='Forløbet blev opdateret i en anden fane. Se situationen igen, før du vælger.';host.querySelector('.turn-body').prepend(notice);return;}const action=b.dataset.turnAction;
    if(action==='listen'){onSound('select');void narrator.read([TURN_VOICE[voiceKey(state)]||TURN_VOICE.observe],{label:'Trafiklab · '+state.stage,trigger:b});return;}
    narrator.stop();
    if(b.dataset.turnView){event('view',b.dataset.turnView);onSound('select');render();return;}
    if(b.dataset.turnAnswer){const answer=b.dataset.turnAnswer;const good=state.stage==='risk'?answer==='cycle':(state.stage==='decision'||state.stage==='repair')?answer==='wait':state.stage==='transfer'?answer==='yield':state.stage==='contrast'?answer==='proceed':answer==='repeat';event('answer',answer);onSound(good?'correct':'repair');render({focus:true});return;}
    if(action==='commit'){event('commit',host.querySelector('#turn-recall')?.value.slice(0,600)||'');onSound('step');render({focus:true});return;}
    if(action==='replay'){replayReady=false;replayAttempt=state.id;render();world.replay(state.decision==='wait'?'wait':'turn');return;}
    if(action==='restart'||action==='review'){start(action==='review');renderedStage='';world.reset();render({focus:true});return;}
    if(action==='next'||action==='retry'){if(action==='next'&&state.stage==='consequence'&&!replayReady)return;event(action);onSound(turnCurrent(getProfile())?.stage==='done'?'complete':'step');render({focus:true});}
  }
  function pick(e){if(disposed||!e.target.closest('.turn-canvas-wrap'))return;const state=turnCurrent(getProfile());if(state.id!==renderedAttempt||state.stage!==renderedStage){render({focus:true});return;}if(state.stage!=='risk')return;narrator.stop();const hit=world.pickRisk?.(e.clientX,e.clientY)||'other';event('point',hit);onSound(hit==='cycle'?'correct':'repair');render({focus:true});}
  host.addEventListener('click',click);host.addEventListener('pointerup',pick);
  const summary=turnSummary(getProfile());if(summary.reviewDue&&summary.latest?.stage==='done')start(true);
  render();
  return {refresh(){this.flush();narrator.stop();render();},flush(){const input=host.querySelector('#turn-recall');if(input&&turnCurrent(getProfile())?.id===renderedAttempt&&turnCurrent(getProfile())?.stage===renderedStage&&input.value!==turnCurrent(getProfile())?.recallText)event('draft',input.value.slice(0,600));},dispose(){this.flush();disposed=true;host.removeEventListener('click',click);host.removeEventListener('pointerup',pick);world?.dispose();narrator.stop();}};
}
